  t2 = rho[0] <= p->dens_threshold;
  t3 = M_CBRT3;
  t4 = rho[0] + rho[1];
  t5 = 0.1e1 / t4;
  t8 = 0.2e1 * rho[0] * t5 <= p->zeta_threshold;
  t9 = p->zeta_threshold - 0.1e1;
  t12 = 0.2e1 * rho[1] * t5 <= p->zeta_threshold;
  t13 = -t9;
  t14 = rho[0] - rho[1];
  t16 = my_piecewise5(t8, t9, t12, t13, t14 * t5);
  t17 = 0.1e1 + t16;
  t18 = t17 <= p->zeta_threshold;
  t19 = POW_1_3(p->zeta_threshold);
  t20 = t19 * p->zeta_threshold;
  t21 = POW_1_3(t17);
  t23 = my_piecewise3(t18, t20, t21 * t17);
  t24 = t3 * t23;
  t25 = POW_1_3(t4);
  t26 = t24 * t25;
  t27 = sigma[0] * sigma[0];
  t28 = rho[0] * rho[0];
  t29 = t28 * t28;
  t30 = t29 * rho[0];
  t31 = POW_1_3(rho[0]);
  t33 = 0.1e1 / t31 / t30;
  t35 = t31 * t31;
  t40 = 0.1e1 + 0.4e-2 * sigma[0] / t35 / t28;
  t41 = t40 * t40;
  t42 = 0.1e1 / t41;
  t43 = t27 * t33 * t42;
  t46 = my_piecewise3(t2, 0, -0.40967043795317740888e-5 * t26 * t43);
  t47 = rho[1] <= p->dens_threshold;
  t48 = -t14;
  t50 = my_piecewise5(t12, t9, t8, t13, t48 * t5);
  t51 = 0.1e1 + t50;
  t52 = t51 <= p->zeta_threshold;
  t53 = POW_1_3(t51);
  t55 = my_piecewise3(t52, t20, t53 * t51);
  t56 = t3 * t55;
  t57 = t56 * t25;
  t58 = sigma[2] * sigma[2];
  t59 = rho[1] * rho[1];
  t60 = t59 * t59;
  t61 = t60 * rho[1];
  t62 = POW_1_3(rho[1]);
  t64 = 0.1e1 / t62 / t61;
  t66 = t62 * t62;
  t71 = 0.1e1 + 0.4e-2 * sigma[2] / t66 / t59;
  t72 = t71 * t71;
  t73 = 0.1e1 / t72;
  t74 = t58 * t64 * t73;
  t77 = my_piecewise3(t47, 0, -0.40967043795317740888e-5 * t57 * t74);
  tzk0 = t46 + t77;

